INSERT INTO layout_templates (id, name, description, width, height, zones) VALUES ('layout-1', 'Bố Cục Chuẩn Sảnh (Video 70% + Cột Poster 30% + Ticker Chân)', 'Phổ biến nhất cho màn hình sảnh đón tiếp khách, vừa phát clip vừa hiển thị poster và chữ chạy thông báo.', 1920, 1080, '[{"id":"zone-1","name":"Khung Video Chính (Trái)","x":0,"y":0,"width":70,"height":90,"zIndex":1,"type":"video","mediaPlaylist":[{"mediaId":"media-1","duration":60},{"mediaId":"media-2","duration":45}]},{"id":"zone-2","name":"Khung Slide Poster Phụ (Phải)","x":70,"y":0,"width":30,"height":55,"zIndex":1,"type":"image_slider","mediaPlaylist":[{"mediaId":"media-3","duration":15},{"mediaId":"media-4","duration":15}]},{"id":"zone-3","name":"Khung Đồng Hồ & Thời Tiết","x":70,"y":55,"width":30,"height":35,"zIndex":2,"type":"widget","widgetType":"clock","mediaPlaylist":[{"mediaId":"media-6","duration":0}]},{"id":"zone-4","name":"Dải Băng Chữ Chạy Chân Trang (Ticker)","x":0,"y":90,"width":100,"height":10,"zIndex":3,"type":"ticker","tickerText":"★ CHÀO MỪNG QUÝ ĐỐI TÁC VÀ KHÁCH HÀNG ĐẾN THAM QUAN HỆ THỐNG TRÌNH CHIẾU LED THÔNG MINH ★ CHÚC QUÝ KHÁCH MỘT NGÀY LÀM VIỆC HIỆU QUẢ VÀ THÀNH CÔNG ★ LIÊN HỆ BỘ PHẬN HỖ TRỢ KỸ THUẬT: 1900 6868 ★","tickerSpeed":18,"tickerBgColor":"#0f172a","tickerTextColor":"#38bdf8","mediaPlaylist":[]}]');
INSERT INTO layout_templates (id, name, description, width, height, zones) VALUES ('layout-2', 'Bố Cục Hội Trường (Toàn Màn Hình 16:9 / 4K)', 'Trình chiếu video full màn hình với độ nét cao không bị che khuất viền vi tính.', 1920, 1080, '[{"id":"zone-main","name":"Khu Vực Phát Toàn Màn Hình","x":0,"y":0,"width":100,"height":100,"zIndex":1,"type":"video","mediaPlaylist":[{"mediaId":"media-1","duration":60},{"mediaId":"media-2","duration":45}]}]');
INSERT INTO layout_templates (id, name, description, width, height, zones) VALUES ('layout-3', 'Bố Cục Kiosk Chân Đứng (Màn Hình Dọc 9:16)', 'Thiết kế tối ưu cho Kiosk thang máy và bảng thông tin cảm ứng dạng dọc.', 1080, 1920, '[{"id":"zone-top","name":"Banner Tiêu Đề Trên Cùng","x":0,"y":0,"width":100,"height":20,"zIndex":1,"type":"image_slider","mediaPlaylist":[{"mediaId":"media-3","duration":10}]},{"id":"zone-center","name":"Video Trung Tâm","x":0,"y":20,"width":100,"height":55,"zIndex":2,"type":"video","mediaPlaylist":[{"mediaId":"media-1","duration":60}]},{"id":"zone-bottom","name":"Tiện Ích Thông Tin & Thời Tiết","x":0,"y":75,"width":100,"height":18,"zIndex":2,"type":"widget","widgetType":"weather","mediaPlaylist":[{"mediaId":"media-6","duration":0}]},{"id":"zone-kiosk-ticker","name":"Dòng Chữ Chạy Cuối","x":0,"y":93,"width":100,"height":7,"zIndex":3,"type":"ticker","tickerText":"Hệ Thống Kiosk Cảm Ứng Thông Minh - Quý Khách Vui Lòng Chạm Để Tra Cứu Thông Tin","tickerSpeed":12,"tickerBgColor":"#1e293b","tickerTextColor":"#f59e0b","mediaPlaylist":[]}]');
INSERT INTO layout_templates (id, name, description, width, height, zones) VALUES ('layout-4', 'Màn Hình LED Ngang Tùy Biến (2560x1080 Ultrawide)', 'Chuyên dụng cho màn hình LED ngoài trời tỉ lệ đặc thù hoặc dải LED chạy dài.', 2560, 1080, '[{"id":"zone-uw-1","name":"Clip Quảng Cáo Trọng Điểm","x":0,"y":0,"width":65,"height":100,"zIndex":1,"type":"video","mediaPlaylist":[{"mediaId":"media-2","duration":45}]},{"id":"zone-uw-2","name":"Khu Vực Thông Tin & Banner Nhãn Hàng","x":65,"y":0,"width":35,"height":85,"zIndex":1,"type":"image_slider","mediaPlaylist":[{"mediaId":"media-4","duration":15},{"mediaId":"media-3","duration":15}]},{"id":"zone-uw-ticker","name":"Dải Băng Chạy Chữ LED","x":65,"y":85,"width":35,"height":15,"zIndex":2,"type":"ticker","tickerText":"LED ULTRA-WIDE DISPLAY SYSTEM ★ HOTLINE ĐẶT QUẢNG CÁO: 0988.360.360","tickerSpeed":15,"tickerBgColor":"#000000","tickerTextColor":"#10b981","mediaPlaylist":[]}]');
